#!/usr/bin/env python3
"""Build static chapters and packed JSON for local/offline browsing."""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parent
DATA=json.loads((ROOT/'data/catalog.json').read_text(encoding='utf8'))
(ROOT/'assets/data.js').write_text('window.DIALECTIC_DATA='+json.dumps(DATA,ensure_ascii=False,separators=(',',':'))+';',encoding='utf8')
nav='''<div class="topline"><span>THE DIALECTIC / BUDGET INTELLIGENCE Morocco</span><span>UN PROJET DE RECHERCHE INDÉPENDANT</span></div><header class="mast"><a class="logo" href="../index.html">THE <strong>DIALECTIC</strong><span class="brand-dot">.</span></a><div class="mast-subtitle">BUDGET INTELLIGENCE <span>Morocco</span></div><div class="signature">UNE ENQUÊTE DE<br><b>UNknown 212</b></div></header><nav class="primary-nav"><div class="navinner"><a class="navlink" href="../index.html#une">À LA UNE</a><a class="navlink" href="../index.html#atlas">CARTE VIVANTE</a><a class="navlink" href="../index.html#ministeres">MINISTÈRES</a><a class="navlink" href="../index.html#cross">CROISEMENTS</a><a class="navlink" href="../index.html#lab">DATA LAB</a><a class="navlink active" href="../index.html#chapitres">18 CHAPITRES</a><a class="navlink" href="../index.html#sources">LES PREUVES</a></div></nav>'''
parts={p['id']:p for p in DATA['parts']}
for c in DATA['chapters']:
    cid=c['id'];p=parts[c['part']]
    chapters=''.join(f'<a class="{"active" if x["id"]==cid else ""}" href="{x["id"]:02d}.html">{x["id"]:02d} · {html.escape(x["title"])}</a>' for x in DATA['chapters'])
    sourceLink='<a href="../index.html#sources" class="btn teal">Vérifier les sources →</a>'
    sec=''.join('<section class="chapter-section"><span class="chapter-counter">'+f'{i+1:02d} / SECTION'+'</span><h2>'+html.escape(s)+'</h2><p>Cette section accueillera les textes critiques, indicateurs économiques, graphiques et documents originaux. Les valeurs seront reliées aux quatre objets : donnée, institution, territoire et projet public.</p><div class="notice">État éditorial : structure prête ; aucune conclusion chiffrée n’est publiée sans source et vérification du périmètre.</div></section>' for i,s in enumerate(c['sections']))
    nxt=DATA['chapters'][cid] if cid<len(DATA['chapters']) else DATA['chapters'][0]
    body=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chapitre {cid:02d} · {html.escape(c['title'])} | The Dialectic</title><link rel="stylesheet" href="../assets/style.css"></head><body>{nav}<main class="main"><div class="chapter-shell"><aside class="chapter-sidebar"><div class="micro">SOMMAIRE · 18 CHAPITRES</div>{chapters}</aside><article class="chapter-article"><a href="../index.html#chapitres" class="small" style="font-weight:800;color:var(--teal)">← Retour aux six parties</a><div style="margin-top:25px" class="strip"><span class="tag">PARTIE {c['part']}</span><span class="tag light">CHAPITRE {cid:02d} / 18</span></div><h1 style="margin:25px 0">{html.escape(c['title'])}</h1><p class="lead">{html.escape(c['question'])}</p><div class="notice green"><b>Démarche éditoriale.</b> Comprendre → comparer → enquêter → vérifier. Les chiffres doivent être accompagnés de l’année, du périmètre, du statut budgétaire et de la source.</div>{sec}<section class="chapter-section"><span class="chapter-counter">PREUVES & MÉTHODOLOGIE</span><h2>Ce qui reste à documenter</h2><p>Documents officiels, séries 2011–2026, programmes ministériels et territorialisation des crédits. Le catalogue partagé est la source de vérité technique ; les simulations d’interface ne sont pas des résultats scientifiques.</p>{sourceLink}</section><div class="actions"><a class="btn primary" href="{nxt['id']:02d}.html">Chapitre suivant : {html.escape(nxt['title'][:46])} →</a><a class="btn" href="../index.html#lab">Data Lab ↗</a></div></article></div></main><footer class="foot"><span>THE DIALECTIC · ENQUÊTE PAR UNknown 212</span><span>V6 — DOCUMENTS ET CHIFFRES TRAÇABLES</span></footer></body></html>'''
    (ROOT/'chapitres'/f'{cid:02d}.html').write_text(body,encoding='utf8')
print('Generated data.js and',len(DATA['chapters']),'chapter pages.')
